", "t": [["write_file", "{"path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\jsondiff-1794053379\\jsondiff.py","content":"import json\n\n\ndef _equal(a, b):\n    \"\"\"Values are equal only when they have the same type and compare equal.\"\"\"\n    if type(a) is not type(b):\n        return False\n    if isinstance(a, dict):\n        if a.keys() != b.keys():\n            return False\n        return all(_equal(a[k], b[k]) for k in a)\n    if isinstance(a, list):\n        if len(a) != len(b):\n            return False\n        return all(_equal(x, y) for x, y in zip(a, b))\n    return a == b\n\n\ndef _render(value):\n    return json.dumps(value, sort_keys=True)\n\n\ndef _walk(path, a, b, out):\n    if _equal(a, b):\n        return\n\n    if isinstance(a, dict) and isinstance(b, dict):\n        for k in a:\n            if k in b:\n                _walk(path + \".\" + k, a[k], b[k], out)\n            else:\n                out.append(\"- %s.%s: %s\" % (path, k, _render(a[k])))\n        for k in b:\n            if k not in a:\n                out.append(\"+ %s.%s: %s\" % (path, k, _render(b[k])))\n        return\n\n    if isinstance(a, list) and isinstance(b, list):\n        common = min(len(a), len(b))\n        for i in range(common):\n            _walk(\"%s[%d]\" % (path, i), a[i], b[i], out)\n        for i in range(len(a), len(b)):\n            out.append(\"+ %s[%d]: %s\" % (path, i, _render(b[i])))\n        for i in range(len(b), len(a)):\n            out.append(\"- %s[%d]: %s\" % (path, i, _render(a[i])))\n        return\n\n    out.append(\"~ %s: %s -> %s\" % (path, _render(a), _render(b)))\n\n\ndef diff(a, b):\n    out = []\n    _walk(\"$\", a, b, out)\n    return sorted(out)\n"}"]]}

